package com.kuaixietech.integration;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import com.kuaixietech.security.DomainAccessGuard;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
class IntegrationConfigurationTest {
 final String root=Base64.getEncoder().encodeToString(new byte[32]);
 @Test void encryptionRandomizesAndAuthenticatesFieldScope(){var c=new IntegrationCipher(root);String a=c.seal("v/p/token","secret"),b=c.seal("v/p/token","secret");assertNotEquals(a,b);assertFalse(a.contains("secret"));assertEquals("secret",c.open("v/p/token",a));assertThrows(IllegalStateException.class,()->c.open("v/another/token",a));assertThrows(IllegalStateException.class,()->c.open("v/p/token",a.substring(0,a.length()-2)+"AA"));}
 @Test void missingMasterKeyCannotFallBackToPlaintext(){var c=new IntegrationCipher("");assertFalse(c.ready());assertThrows(IllegalStateException.class,()->c.seal("scope","secret"));assertThrows(IllegalStateException.class,()->new IntegrationCipher(root).open("scope","old-plaintext-secret"));}
 @Test void unknownProtocolCannotBeInventedByConfig(){assertThrows(IllegalArgumentException.class,()->IntegrationCatalog.product("fake","pay"));assertThrows(IllegalArgumentException.class,()->IntegrationCatalog.credentialBundle("lowercase"));}
 @Test void catalogNeverReturnsSecretOrCiphertext(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);var cipher=new IntegrationCipher(root);String token=cipher.seal("http-adapter/rtc-call/bearer_token","never-return-this-token");when(db.queryForList(anyString(),any(Object[].class))).thenAnswer(call->{String sql=call.getArgument(0);Object[] args=(Object[])call.getRawArguments()[1];return sql.contains("field_cipher")&&args.length==2&&"http-adapter".equals(args[0])&&"rtc-call".equals(args[1])?List.of(Map.of("field_key","bearer_token","field_cipher",token)):List.of();});var c=new IntegrationConfiguration(db,guard,cipher,mock(IntegrationHttp.class));String result=c.catalog().toString();assertFalse(result.contains("never-return-this-token"));assertFalse(result.contains(token));assertTrue(result.contains("stored"));verify(guard).requireAdmin();}
 @Test void unauthorizedConfigurationReadsAndWritesStopBeforeDatabase(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);when(guard.requireAdmin()).thenThrow(new SecurityException());var c=new IntegrationConfiguration(db,guard,new IntegrationCipher(root),mock(IntegrationHttp.class));assertThrows(SecurityException.class,c::catalog);assertThrows(SecurityException.class,()->c.save("aliyun","sms",new IntegrationConfiguration.Input(false,"",Map.of(),List.of())));verifyNoInteractions(db);}
 @Test void unknownFieldsAreRejectedBeforeWrites(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);var c=new IntegrationConfiguration(db,guard,new IntegrationCipher(root),mock(IntegrationHttp.class));assertThrows(IllegalArgumentException.class,()->c.save("aliyun","sms",new IntegrationConfiguration.Input(false,"",Map.of("arbitrary_url","https://evil.example"),List.of())));verifyNoInteractions(db);}
 @Test void storedDisabledBundleMustNotUseEnvironmentFallback(){var c=mock(IntegrationConfiguration.class);when(c.exists("credentials","WECHAT_MAIN")).thenReturn(true);when(c.runtime("credentials","WECHAT_MAIN")).thenReturn(null);assertThrows(IllegalStateException.class,()->new IntegrationCredentials(c).required("WECHAT_MAIN","APP_ID"));}
 @Test void credentialBundlesCannotOverrideMerchantIdentitySnapshots(){var c=mock(IntegrationConfiguration.class);when(c.exists("credentials","WECHAT_MAIN")).thenReturn(true);when(c.runtime("credentials","WECHAT_MAIN")).thenReturn(Map.of("APP_ID","new-app"));assertEquals("new-app",new IntegrationCredentials(c).required("WECHAT_MAIN","APP_ID"));assertThrows(IllegalStateException.class,()->new IntegrationCredentials(c).required("WECHAT_MAIN","MERCHANT_ID"));}
 @Test void referenceOnlyProductsCannotBeEnabled(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);var c=new IntegrationConfiguration(db,guard,new IntegrationCipher(root),mock(IntegrationHttp.class));var e=assertThrows(IllegalArgumentException.class,()->c.save("aliyun","green",new IntegrationConfiguration.Input(true,"",Map.of(),List.of())));assertEquals("INTEGRATION_ADAPTER_NOT_IMPLEMENTED",e.getMessage());verify(db,never()).update(startsWith("UPDATE t_integration_settings SET enabled"),any(Object[].class));}
 @Test void legacyDeliveryErrorsAreRedacted(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);when(db.queryForList(anyString())).thenReturn(List.of(Map.of("id",1,"error","phone=13800138000 code=123456 token=secret")));var controller=new IntegrationAdminController(mock(IntegrationConfiguration.class),db,guard);assertEquals("LEGACY_ERROR_REDACTED",controller.deliveries().getFirst().get("error"));verify(guard).requireAdmin();}
 @Test void smsEnabledConfigurationUsesNativeWorkerWithoutLegacyDoubleSend(){var gateway=mock(LegacyCloudFunctionBridge.class);var sms=mock(SmsOutboxDispatcher.class);when(sms.configured()).thenReturn(true);new com.kuaixietech.scheduler.ContactCodeDeliveryScheduler(gateway,sms,true).run();verify(sms).run();verifyNoInteractions(gateway);}
 @Test void disabledNativeAndLegacyModesNeverDispatch(){var gateway=mock(LegacyCloudFunctionBridge.class);var sms=mock(SmsOutboxDispatcher.class);new com.kuaixietech.scheduler.ContactCodeDeliveryScheduler(gateway,sms,false).run();verify(sms,never()).run();verifyNoInteractions(gateway);}
 @Test void enabledUnreadableConfigurationFailsClosed(){var db=mock(JdbcTemplate.class);when(db.queryForList(startsWith("SELECT enabled"),any(Object[].class))).thenReturn(List.of(Map.of("enabled",1)));when(db.queryForList(startsWith("SELECT field_key"),any(Object[].class))).thenReturn(List.of(Map.of("field_key","app_secret","field_cipher","old-value")));var c=new IntegrationConfiguration(db,mock(DomainAccessGuard.class),new IntegrationCipher(root),mock(IntegrationHttp.class));assertThrows(IllegalStateException.class,()->c.runtime("wechat","miniprogram"));}
}
